BEGIN;
CREATE TABLE claims(claim_id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites,field TEXT NOT NULL,value TEXT NOT NULL,evidence_class TEXT NOT NULL CHECK(evidence_class IN ('WEB_PRIMARY','WEB_COMPANY','WEB_SECONDARY','MODEL_UNVERIFIED','LEGACY_PENDING','INFERRED')),source_id TEXT REFERENCES sources,scope TEXT,observed_date TEXT,CHECK(evidence_class NOT LIKE 'WEB_%' OR source_id IS NOT NULL),CHECK(evidence_class!='MODEL_UNVERIFIED' OR source_id IS NULL));
CREATE TABLE search_log(log_id TEXT PRIMARY KEY,site_id TEXT REFERENCES sites,work_package TEXT NOT NULL,query TEXT NOT NULL,source_id TEXT REFERENCES sources,result TEXT NOT NULL,next_action TEXT,search_date TEXT NOT NULL);
CREATE TABLE site_relations(relation_id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites,other_site_id TEXT NOT NULL REFERENCES sites,relation TEXT NOT NULL,status TEXT NOT NULL,source_id TEXT REFERENCES sources,notes TEXT);
UPDATE sites SET permit_id='91210200677529168F001V',capacity_summary=capacity_summary||'；2025改建验收范围7750吨/年催化剂及分子筛（非全厂新增）',water_summary=water_summary||'；2025验收含镍废水车间沉淀后入全厂污水站，再纳管松木岛园区',source_status='部分本轮复核' WHERE site_id='CN0026';
UPDATE sites SET status='历史线索主体待核；可能与CN0194重复',capacity_summary='20000吨/年历史项目线索；2024政府公示主体湖北润驰，催化剂线尚未建设',notes=notes||'；不可认定科林独立在产基地' WHERE site_id='CN0075';
UPDATE sites SET permit_id='91340700MA2UW7F580001V',capacity_summary='企业披露2023投产，11000吨/年产品含载体，催化剂净产能待核',source_status='部分本轮复核' WHERE site_id='CN0097';
UPDATE sites SET address='临淄区胜利炼油厂沥青南路3号',capacity_summary='2023重点技改项目5000吨/年；验收及有效产能未核',source_status='部分本轮复核' WHERE site_id='CN0088';
UPDATE tasks SET state='部分完成',missing='全厂污水站工艺及水量、实际负荷、拟建5200t/d进度' WHERE site_id='CN0026';
UPDATE tasks SET state='部分完成',missing='核对与湖北润驰主体关系及二期建设进度；禁止双计' WHERE site_id='CN0075';
UPDATE tasks SET state='部分完成',missing='11000吨产品分项；排污许可执行报告及工艺、水量' WHERE site_id='CN0097';
UPDATE tasks SET state='部分完成',missing='5000吨技改验收与当前产能、废水工艺' WHERE site_id='CN0088';
COMMIT;
